namespace Astronomy;
public interface ILatLongService
{
    Task<(double Latitude, double Longitude)> GetLatLong();
}

namespace Astronomy;
public class LatLongService : ILatLongService
{
    public async Task<(double Latitude, double Longitude)> GetLatLong()
    {
        double latLoc = 0.0;
        double longLoc = 0.0;
        PermissionStatus status = await Permissions.RequestAsync<Permissions.LocationWhenInUse>();
        if (status == PermissionStatus.Granted)
        {
            GeolocationRequest request = new GeolocationRequest(GeolocationAccuracy.Default, TimeSpan.FromSeconds(10));
            Location? location = await Geolocation.GetLocationAsync(request);
            latLoc = location.Latitude;
            longLoc = location.Longitude;
        }

        return (latLoc, longLoc);
    }
}

namespace Astronomy;
public static class MoonPhaseCalculator
{
    public enum Phase
    {
        New,
        WaxingCrescent,
        FirstQuarter,
        WaxingGibbous,
        Full,
        WaningGibbous,
        LastQuarter,
        WaningCrescent,
    }

    static double synodicLength = 29.530588853; //Duración en días de un ciclo lunar completo.
    static DateTime referenceNewMoonDate = new DateTime(2017, 11, 18);
    public static Phase GetPhase(DateTime date)
    {
        return GetPhase(GetAge(date));
    }

    static double GetAge(DateTime date)
    {
        double days = (date - referenceNewMoonDate).TotalDays;
        return days % synodicLength;
    }

    static Phase GetPhase(double age)
    {
        if (age < 1)
            return Phase.New;
        if (age < 7)
            return Phase.WaxingCrescent;
        if (age < 8)
            return Phase.FirstQuarter;
        if (age < 14)
            return Phase.WaxingGibbous;
        if (age < 15)
            return Phase.Full;
        if (age < 22)
            return Phase.WaningGibbous;
        if (age < 23)
            return Phase.LastQuarter;
        if (age < 29)
            return Phase.WaningCrescent;
        return Phase.New;
    }
}

using System.Text.Json;

namespace Astronomy;
public class SunriseService
{
    const string SunriseSunsetServiceUrl = "https://api.sunrise-sunset.org";
    public async Task<(DateTime Sunrise, DateTime Sunset)> GetSunriseSunsetTimes(double latitude, double longitude)
    {
        string query = $"{SunriseSunsetServiceUrl}/json?lat={latitude}&lng={longitude}&date=today";
        HttpClient client = new HttpClient();
        client.DefaultRequestHeaders.Add("Accept", "application/json");
        string json = await client.GetStringAsync(query);
        JsonSerializerOptions options = new JsonSerializerOptions
        {
            PropertyNameCaseInsensitive = true
        };
        SunriseSunsetData? data = JsonSerializer.Deserialize<SunriseSunsetData>(json, options);
        return (DateTime.Parse(data.Results.Sunrise), DateTime.Parse(data.Results.Sunset));
    }

    class SunriseSunsetData
    {
#pragma warning disable 0649
        // El campo se asigna mediante deserialización JSON; se desactiva la advertencia de campo sin asignación.
        //public SunriseSunsetResults Results;
        public SunriseSunsetResults Results { get; set; }
#pragma warning restore 0649
    }

    class SunriseSunsetResults
    {
#pragma warning disable 0649
        // Los campos se asignan mediante deserialización JSON; se desactiva la advertencia de campos sin asignación.
        public string Sunrise { get; set; }
        public string Sunset { get; set; }
#pragma warning restore 0649
    }
}

