/// <summary>
/// Creación de Extensión para establecer el valor del Espaciado según la Plataforma
/// </summary>
[AcceptEmptyServiceProvider]
public class EspaciadoExtension : IMarkupExtension
{
    public object ProvideValue(IServiceProvider serviceProvider)
    {
        string plataforma = DeviceInfo.Platform.ToString();
        double espaciado = 0;
        switch (plataforma)
        {
            case "WinUI":
                espaciado = EntryContraseniaV2.EspaciadoWindows;
                break;
            case "Android":
                espaciado = EntryContraseniaV2.EspaciadoAndroid;
                break;
        }

        return espaciado;
    }
}

